# Generated by manage.py generate_test_cases.
"""Provider-owned cleanup through the shared call controller."""

from django.http import HttpResponse

from bloomerp.communication.builtins.voip.controller import VoIPController
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)

from .fixtures import ComponentFixtures


class TestCancelCallComponent(ComponentFixtures, BloomerpComponentTestCase):
    view_name = "components_voip_cancel_call"

    def prepare_call(self, scenario: RequestScenario) -> None:
        """Reserve the current actor's outgoing telephone call."""
        self.prepare_request(scenario)
        self.call = VoIPController(self.normal_user).prepare_call(
            self.chat.pk, "cancel-shared"
        )
        scenario.view_kwargs = {"call_id": self.call.pk}

    def canceled(self, response: HttpResponse) -> bool:
        """Keep a terminal record after media establishment is abandoned."""
        self.call.refresh_from_db()
        return self.call.status == "failed" and self.call.ended_at is not None

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Verify cancellation and ownership without deleting phone history."""
        return [
            RequestScenario(
                name="Cancel own reservation",
                method="POST",
                user=self.normal_user,
                prepare=self.prepare_call,
                expected=ExpectedResult(response_validators=self.canceled),
            ),
            RequestScenario(
                name="Reject other actor",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_call,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="GET cannot cancel",
                user=self.normal_user,
                prepare=self.prepare_call,
                expected=ExpectedResult(status_code=405),
            ),
        ]
